esearchAttempt(                         locked.Map, targetFloorKey, frame, mapOpenAttempt,                         isOtherFloor ? "floor-switch" : "map-open",                         isOtherFloor ? locked.Result.OverlayTransform : null);                 }                 finally                 {                     researchRecord?.Complete();                 }             }             var publishOutcome = await PublishMapOpenAlignmentResultAsync(                     toggle,                     operationMatch,                     frame,                     locked,                     targetFloorKey,                     recoveringSelectedIdentity,                     aligned,                     failureReason,                     repairCacheKey,                     resetRecoveredScaleState);             if (publishOutcome == MapOpenAlignmentPublishOutcome.Superseded)             {                 trace?.SetTerminal("superseded", "map-operation-version-changed");                 return;             }             if (publishOutcome == MapOpenAlignmentPublishOutcome.Failed)             {                 trace?.SetTerminal("failed", "alignment-not-accepted");             }         }         catch (OperationCanceledException)         {             throw;         }         catch (Exception ex)         {             trace?.SetTerminal("failed", $"exception:{ex.GetType().Name}");             _statusMessage = $"仅对齐异常：{ex.Message}";             _logCollector.Append(                 MapLogCategory.ScanLifecycle,                 MapLogLevel.Error,                 _statusMessage,                 details: new()                 {                     ["exceptionType"] = ex.GetType().FullName,                     ["stackTrace"] = ex.ToString()                 });             var failureOverlay = trace?.StartTopLevel(                 "overlay_publish",                 MapOperationWaitKind.Compute,                 mapId: locked.Map.Id.ToString("D"),                 floorKey: targetFlo